(function(){'use strict';const R=CritterRenderer.prototype,{BAT,ROPE,THEMES}=Critters,paint=R.paintGround,projectile=R.projectile,weapon=R.weapon,event=R.event,effects=R.effects;
R.paintGround=function(){paint.call(this);const k=this.gc,t=THEMES[this.game.options.theme];for(const s of this.game.structures||[]){k.save();const gr=k.createLinearGradient(0,s.y,0,s.y+s.h);gr.addColorStop(0,'#e9d4a6');gr.addColorStop(.2,t.grass);gr.addColorStop(.3,'#64767d');gr.addColorStop(1,'#344a58');k.fillStyle=gr;k.strokeStyle='#243e4b';k.lineWidth=3;k.fillRect(s.x,s.y,s.w,s.h);k.strokeRect(s.x+1,s.y+1,s.w-2,s.h-2);k.strokeStyle='#c7d3be88';k.lineWidth=2;for(let x=s.x+12;x<s.x+s.w-10;x+=24){k.beginPath();k.moveTo(x,s.y+s.h-3);k.lineTo(x+17,s.y+6);k.stroke();}for(const x of [s.x+15,s.x+s.w-15]){k.fillStyle='#e9c879';k.beginPath();k.arc(x,s.y+s.h-6,4,0,7);k.fill();}k.restore();}this.holeCount=0;this.cutHoles();};
R.event=function(e){event.call(this,e);if(e.type==='batSwing'){this.batSwing={id:e.id,life:.38,face:e.face,hit:e.hit};if(e.hit!==null){this.shake=this.reduced?0:7;const u=this.game.units[e.hit];this.texts.push({x:u.x,y:u.y-60,text:'HOMERUN!',life:1,color:'#ffe0a0'});}}if(e.type==='ropeAttach'){this.rings.push({x:e.x,y:e.y,r:16,life:.3,max:.3});}};
R.weapon=function(k,id,x,y,s=1){if(id!==BAT&&id!==ROPE)return weapon.call(this,k,id,x,y,s);k.save();k.translate(x,y);k.scale(s,s);k.strokeStyle='#34434d';k.lineWidth=2;if(id===BAT){k.rotate(-.4);k.fillStyle='#c58a50';k.beginPath();k.moveTo(-29,-3);k.lineTo(4,-6);k.quadraticCurveTo(31,-12,32,0);k.quadraticCurveTo(31,12,4,6);k.lineTo(-29,3);k.closePath();k.fill();k.stroke();k.fillStyle='#f0cf96';k.fillRect(5,-6,16,12);k.fillStyle='#5a6268';k.fillRect(-25,-4,13,8);}else{k.fillStyle='#91ada6';k.beginPath();k.arc(-6,0,15,0,7);k.fill();k.stroke();k.strokeStyle='#e6d4ad';k.lineWidth=3;for(let i=0;i<3;i++){k.beginPath();k.arc(-6,0,5+i*3,0,7);k.stroke();}k.strokeStyle='#bed5db';k.beginPath();k.moveTo(7,0);k.lineTo(23,-7);k.lineTo(31,-17);k.moveTo(23,-7);k.lineTo(33,-4);k.stroke();}k.restore();};
R.projectile=function(k){const r=this.game.rope;if(r){const u=this.game.units[r.id];k.save();k.lineWidth=4;k.strokeStyle='#193b49';k.beginPath();k.moveTo(r.x,r.y);k.lineTo(u.x,u.y-9);k.stroke();k.strokeStyle='#e8d8a7';k.lineWidth=2;k.setLineDash([7,3]);k.stroke();k.setLineDash([]);k.fillStyle='#e6d8a7';k.beginPath();k.arc(r.x,r.y,5,0,7);k.fill();k.restore();}projectile.call(this,k);};
R.effects=function(k,dt){effects.call(this,k,dt);const b=this.batSwing;if(!b)return;if(!this.game.paused)b.life-=dt;if(b.life<=0){this.batSwing=null;return;}const u=this.game.units[b.id],p=1-b.life/.38;k.save();k.translate(u.x,u.y-9);k.scale(b.face,1);if(!this.reduced){k.strokeStyle='#fff0b1';k.globalAlpha=(1-p)*.75;k.lineWidth=7;k.beginPath();k.arc(0,0,64,-1.7+p*.4,1.2+p*.4);k.stroke();k.globalAlpha=1;}k.rotate(-1.8+p*3.1);this.weapon(k,BAT,30,0,1);k.restore();};
const trajectory=R.trajectory;R.trajectory=function(k){const g=this.game;if(g.weapon!==BAT&&g.weapon!==ROPE)return trajectory.call(this,k);if(!g.canFire())return;const u=g.active;k.save();if(g.weapon===BAT){k.translate(u.x,u.y);k.scale(u.face,1);k.strokeStyle='#f4d28c88';k.lineWidth=2;k.setLineDash([5,6]);k.beginPath();k.arc(0,0,90,-.75,.75);k.stroke();}else if(!g.rope){const a=g.angle*Math.PI/180,start={x:u.x,y:u.y-14};let end={x:start.x+Math.cos(a)*560,y:start.y-Math.sin(a)*560},hit=false;for(let d=25;d<=560;d+=3){const x=start.x+Math.cos(a)*d,y=start.y-Math.sin(a)*d;if(g.solid(x,y)){end={x,y};hit=true;break;}}k.strokeStyle=hit?'#ffdf90aa':'#d7eee577';k.lineWidth=2;k.setLineDash([5,8]);k.beginPath();k.moveTo(start.x,start.y);k.lineTo(end.x,end.y);k.stroke();k.setLineDash([]);if(hit){k.beginPath();k.arc(end.x,end.y,10,0,7);k.stroke();}}k.restore();};
})();
